# Receives Telegram Bot API Update JSON via webhook
from shared.message_normalizer import normalize_message, format_response

# azure-function-crm/shared/message_normalizer.py
SUPPORTED_CHANNELS = ("widget", "email", "telegram", "whatsapp")

def normalize_message(channel: str, raw_payload: dict, user_id: str) -> dict:
    """Returns: {"text": str, "user_id": str, "channel": str, "metadata": dict}"""
    if channel == "widget": return _normalize_widget(raw_payload, user_id)
    elif channel == "telegram": return _normalize_telegram(raw_payload, user_id)

# azure-function-crm/shared/otp_storage.py
otp_store: Dict[str, Dict[str, Any]] = {}
otp_store_lock = threading.Lock()

